local function UiHookMenuCommand(filter)
  if type(rawget(_ENV, "funcLuaMenuCommand")) == "function" then
    rawset(_ENV, "funcLuaMenuCommand", UiInstallMenuWrap(rawget(_ENV, "funcLuaMenuCommand"), filter))
