-- the slot buy_btn_dmy01 and, on the right, a teal check (_icon_check_buy01) when the game reports the Deluxe Edition
-- as owned or a cart (_icon_buy01) when not: both driven by funcLuaCommand(2127863466). Accept on it: owned = the
-- error sound only; not owned = the «open the store?» window (text title_open_shop_window_1) and then the platform
-- store page of the Deluxe Edition. Nothing else in the game is reached through it.
-- Clean HUD: no pill, no check / cart; owned = only the logo (a badge), not owned = the layer hidden. In both cases the
-- layer takes no focus: no controller focus (CMND_SET_ENABLE_CTRL_FOCUS false), no mouse zone / hover, Accept on it
-- swallowed, and a focus the retail focus graph (title_menu_2_setting: the lower row's CMD_FCS_BACK shift) still sends
-- to it goes straight back to the item that had it, so there is no empty focus stop. The ownership is the game's own
-- value, read at every pass. Flag: deluxe_badge (Clean HUD ui_flags.toml, on by default).
local UI_DX_LAYER = 3427392471
local UI_DX_MESHES = {
  2781781827,    -- _buy_btn_base01: the white pill
  1714296966,      -- _buy_btn_ok01: pill, decided state
  1667304963,      -- _buy_btn_ol01: pill, focus outline
  3487882952,  -- _icon_check_buy01: the teal check (owned)
  2381063373,        -- _icon_buy01: the cart (not owned)
}
local UI_DX_LOWER = 3873872512   -- fallback focus: the lower row (Guía / Opciones / Información)
local UI_DX_OWNED = 2127863466            -- funcLuaCommand: true = Deluxe Edition owned (retail check-mark switch)
local CMND_SET_MESH_VISIBLE = 3405944500
local CMND_SET_LAYER_VISIBLE = 711242136
local CMND_IS_OPEN_LAYER = 2640875187
local CMND_GET_CREATE_LAYER_NUM = 1175615627
local CMND_SET_ENABLE_CTRL_FOCUS = 3518307824
local CMND_SET_HIT_ZONE = 855005857       -- (layer, idx, bool): the instance's mouse zone
local CMND_SET_ON_CHANGE_FOCUS_MOUSE = 2206938151
local CMND_FOCUS_INSTANCE = 1778826357    -- (layer, idx, bool): retail OnFunction moves the focus with it
local UI_DX_EVERY = 30                    -- Step frames between two passes
local ui_dx_frames = 0
local ui_dx_logged = false

local function UiDxCmd(...)
  if type(funcLuaMenuCommand) ~= "function" then
    return false
  end
  local ok, r = pcall(funcLuaMenuCommand, ...)
  return ok and r
end

local function UiDxOwned()
  if type(funcLuaCommand) ~= "function" then
    return false
  end
  local ok, r = pcall(funcLuaCommand, UI_DX_OWNED)
  return ok and r == true
end

-- the badge look and the focus removal on every instance of the layer (retail opens it with 1 of its 3 instances)
local function UiDxApply()
  if not UiOn("deluxe_badge") or not UiDxCmd(CMND_IS_OPEN_LAYER, UI_DX_LAYER, 0) then
    return
  end
  local owned = UiDxOwned()
  if not ui_dx_logged then
    ui_dx_logged = true
    UiLog("deluxe_badge owned", owned)
  end
  UiDxCmd(CMND_SET_ENABLE_CTRL_FOCUS, UI_DX_LAYER, false)
  local n = UiDxCmd(CMND_GET_CREATE_LAYER_NUM, UI_DX_LAYER)
  if type(n) ~= "number" or n < 1 then
